"""Offline contract check against JSON schemas generated by the pinned Codex binary.

Does not start app-server, read credentials, execute a turn, or access the network.
Supply the local generated schema directory; the product runtime is unchanged.
"""
import argparse
import json
from pathlib import Path


def load(root, path):
    return json.loads((root / path).read_text(encoding="utf-8"))


def methods(schema):
    return {
        value
        for option in schema["oneOf"]
        for value in option.get("properties", {}).get("method", {}).get("enum", [])
    }


def verify(root):
    contracts = {
        "ClientRequest": {"initialize", "thread/start", "thread/resume", "thread/read",
                          "thread/list", "turn/start", "turn/steer", "turn/interrupt"},
        "ClientNotification": {"initialized"},
        "ServerRequest": {"item/commandExecution/requestApproval",
                          "item/fileChange/requestApproval", "item/permissions/requestApproval"},
        "ServerNotification": {"thread/started", "thread/status/changed", "turn/started",
                               "turn/completed", "item/agentMessage/delta",
                               "item/commandExecution/outputDelta", "thread/tokenUsage/updated"},
    }
    for name, required in contracts.items():
        missing = required - methods(load(root, name + ".json"))
        if missing:
            raise ValueError(f"{name}: missing {sorted(missing)}")
    fields = {
        "ThreadStartParams": {"cwd", "sandbox", "approvalPolicy", "ephemeral"},
        "ThreadResumeParams": {"threadId", "cwd", "sandbox", "approvalPolicy"},
        "ThreadReadParams": {"threadId", "includeTurns"},
        "TurnStartParams": {"threadId", "input", "sandboxPolicy", "approvalPolicy"},
        "TurnInterruptParams": {"threadId", "turnId"},
    }
    for name, required in fields.items():
        missing = required - set(load(root, "v2/" + name + ".json")["properties"])
        if missing:
            raise ValueError(f"{name}: missing {sorted(missing)}")
    for name, required in {
        "ThreadResumeParams": {"threadId"},
        "ThreadReadParams": {"threadId"},
        "TurnStartParams": {"threadId", "input"},
        "TurnInterruptParams": {"threadId", "turnId"},
    }.items():
        actual = set(load(root, "v2/" + name + ".json")["required"])
        if not required <= actual:
            raise ValueError(f"{name}: required identity lost")
    # Approval response schemas must exist; the host must explicitly map denial
    # and scope before implementing the live RPC adapter.
    for name in ("CommandExecutionRequestApproval", "FileChangeRequestApproval",
                 "PermissionsRequestApproval"):
        for suffix in ("Params", "Response"):
            load(root, name + suffix + ".json")
    return {"method_groups": len(contracts), "parameter_groups": len(fields),
            "required_identity_groups": 4, "approval_schema_pairs": 3}


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("schema_dir", type=Path)
    args = parser.parse_args()
    print(json.dumps(verify(args.schema_dir), sort_keys=True))
